target.css:
:root {
  --ink: #20252b;
  --muted: #6f7780;
  --paper: #fffdf8;
  --line: #d9d6cd;
  --slate: #eef1f0;
  --teal: #187f7a;
  --teal-pale: #d9f0eb;
  --coral: #d75448;
  --amber: #d99b36;
  --white: #ffffff;
}

.cue-card {
  width: 500px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.cue-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.project h1 {
  margin: 2px 0 0;
  font-size: 21px;
  font-weight: 750;
  letter-spacing: -0.5px;
  line-height: 1;
}

.eyebrow,
.panel-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 1px;
  line-height: 1;
}

.recording-state {
  padding: 6px 8px;
  border-radius: 5px;
  background: var(--coral);
  color: var(--white);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.cue-content {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 148px;
  min-height: 158px;
}

.timeline {
  padding: 13px 16px 12px;
}

.scene-meta {
  display: flex;
  justify-content: space-between;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.45px;
}

.scene-meta strong {
  color: var(--ink);
}

.timebar {
  position: relative;
  height: 5px;
  margin: 9px 0 10px;
  border-radius: 5px;
  background: var(--line);
}

.playhead {
  display: block;
  width: 42%;
  height: 100%;
  border-radius: inherit;
  background: var(--teal);
}

.playhead::after {
  position: absolute;
  top: -3px;
  right: 56%;
  width: 11px;
  height: 11px;
  border: 2px solid var(--paper);
  border-radius: 50%;
  background: var(--teal);
  content: "";
}

.cue-list {
  display: grid;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.cue-row {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) 56px;
  align-items: center;
  min-height: 25px;
  border-radius: 5px;
  color: var(--muted);
  font-size: 11px;
}

.cue-row.active {
  padding: 0 6px;
  background: var(--teal-pale);
  color: var(--ink);
  font-weight: 750;
}

.cue-number {
  color: var(--teal);
  font-size: 10px;
  font-weight: 800;
}

.cue-time {
  text-align: right;
  font-size: 10px;
  font-weight: 700;
}

.mix-panel {
  display: flex;
  flex-direction: column;
  gap: 11px;
  padding: 14px 12px 12px;
  border-left: 1px solid var(--line);
  background: var(--slate);
}

.level-row {
  display: grid;
  grid-template-columns: 29px 1fr 31px;
  align-items: center;
  gap: 5px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.3px;
}

.level-row strong {
  color: var(--ink);
  font-size: 9px;
  letter-spacing: 0;
}

.meter {
  display: block;
  height: 6px;
  overflow: hidden;
  border-radius: 4px;
  background: var(--line);
}

.meter i {
  display: block;
  width: 68%;
  height: 100%;
  border-radius: inherit;
  background: var(--teal);
}

.meter.amber i {
  width: 84%;
  background: var(--amber);
}

button {
  margin-top: auto;
  padding: 7px 4px;
  border: 1px solid var(--ink);
  border-radius: 5px;
  background: var(--paper);
  color: var(--ink);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.cue-footer {
  display: flex;
  align-items: center;
  gap: 17px;
  padding: 9px 16px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 9px;
  font-weight: 750;
  letter-spacing: 0.5px;
}

.cue-footer strong {
  color: var(--ink);
}

.take-count {
  margin-left: auto;
  color: var(--teal);
  font-weight: 800;
}

